## Why This Is Asked

This question tests understanding of Go-C interop boundaries, memory ownership, and callback-based asynchronous flows in CGO. The candidate must design a safe pattern for per-input callbacks, ordering guarantees, and memory cleanup under concurrency.

## Key Concepts

- CGO callbacks and //export directives
- Cross-language memory management (malloc/free)
- Synchronization and ordering in Go when callbacks arrive from C
- Safe memory copying between C and Go heaps

## Code Example

```go
package main

/*
#include <stdlib.h>
#include <string.h>

typedef struct {
    void *ctx;
    int index;
    const char *result;
    size_t len;
} CallbackContext;

extern void goCallback(CallbackContext *cbCtx);

static int batch_process_wrapper(
    const char **inputs,
    size_t n,
    void (*cb)(const char *result, size_t len, void *ctx),
    void *ctx
) {
    for (size_t i = 0; i < n; i++) {
        cb(inputs[i], strlen(inputs[i]), ctx);
    }
    return 0;
}

static void cCallback(const char *result, size_t len, void *ctx) {
    CallbackContext *cbCtx = (CallbackContext *)ctx;
    cbCtx->result = result;
    cbCtx->len = len;
    goCallback(cbCtx);
}

//export goCallback
extern void goCallback(CallbackContext *cbCtx);
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

type Result struct {
    Index int
    Data  string
    Err   error
}

func BatchProcess(inputs []string) ([]string, error) {
    if len(inputs) == 0 {
        return []string{}, nil
    }

    cInputs := make([]*C.char, len(inputs))
    defer func() {
        for _, cStr := range cInputs {
            C.free(unsafe.Pointer(cStr))
        }
    }()

    for i, s := range inputs {
        cStr := C.CString(s)
        cInputs[i] = cStr
    }

    results := make([]string, len(inputs))
    var wg sync.WaitGroup
    resultCh := make(chan Result, len(inputs))

    ctx := C.malloc(C.sizeof_char * C.size_t(len(inputs)))
    defer C.free(ctx)

    wrapper := func() {
        defer wg.Done()
        for i := 0; i < len(inputs); i++ {
            callbackCtx := &C.CallbackContext{
                ctx:   ctx,
                index: C.int(i),
            }
            ret := C.batch_process_wrapper((**C.char)(unsafe.Pointer(&cInputs[i])), 1, C.cCallback, unsafe.Pointer(callbackCtx))
            if ret != 0 {
                resultCh <- Result{Index: i, Err: fmt.Errorf("batch_process failed with code %d", ret)}
                return
            }
        }
    }

    wg.Add(1)
    go wrapper()

    go func() {
        wg.Wait()
        close(resultCh)
    }()

    for result := range resultCh {
        if result.Err != nil {
            return nil, result.Err
        }
        results[result.Index] = result.Data
    }

    return results, nil
}

func main() {
    inputs := []string{"hello", "world", "foo", "bar"}

    var wg sync.WaitGroup
    for i := 0; i < 4; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            results, err := BatchProcess(inputs)
            if err != nil {
                fmt.Printf("Goroutine %d: Error: %v\n", id, err)
                return
            }
            fmt.Printf("Goroutine %d: Results: %v\n", id, results)
        }(i)
    }

    wg.Wait()
    fmt.Println("All goroutines completed")
}
```

## Why This Is Asked
This question tests your ability to model cross-language callbacks, manage memory ownership, and handle streaming data in CGO. You must coordinate Go and C lifetimes, ensure safe callbacks from C into Go, and design backpressure-aware consumption.

## Key Concepts
- **CGO callbacks**: Exporting Go functions for C to call safely using cgo export
- **Memory ownership**: C allocates chunks via `malloc`, Go frees them to prevent leaks
- **Streaming via channels**: Using Go channels to receive pushed data from C
- **Backpressure**: Ensuring the consumer can signal when it cannot keep up
- **Thread safety**: Managing concurrent access to shared state between C threads and Go runtime

## Code Example
```c
// cgowa_stream.h
typedef void (*chunk_cb)(const char* data, size_t len, void* user);

void* start_stream(const char* source_id, chunk_cb on_chunk, void* user);
void stop_stream(void* handle);
```

```c
// cgowa_stream.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "cgowa_stream.h"

struct stream_context {
    chunk_cb callback;
    void* user;
    pthread_t thread;
    int running;
};

static void* stream_thread(void* arg) {
    struct stream_context* ctx = arg;
    const char* chunks[] = {"{\"id\":1}", "{\"id\":2}", "{\"id\":3}"};

    for (int i = 0; i < 3 && ctx->running; i++) {
        size_t len = strlen(chunks[i]);
        ctx->callback(chunks[i], len, ctx->user);
        sleep(1);
    }
    return NULL;
}

void* start_stream(const char* source_id, chunk_cb on_chunk, void* user) {
    struct stream_context* ctx = malloc(sizeof(struct stream_context));
    ctx->callback = on_chunk;
    ctx->user = user;
    ctx->running = 1;
    pthread_create(&ctx->thread, NULL, stream_thread, ctx);
    return ctx;
}

void stop_stream(void* handle) {
    struct stream_context* ctx = handle;
    ctx->running = 0;
    pthread_join(ctx->thread, NULL);
    free(ctx);
}
```

```go
// stream.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lstream
#include "cgowa_stream.h"
#include <stdlib.h>

extern void chunkProxy(const char* data, size_t len, void* user);

static void* go_start_stream(const char* source_id, void* user) {
    return start_stream(source_id, chunkProxy, user);
}
*/
import "C"

import (
    "encoding/json"
    "fmt"
    "runtime"
    "sync"
    "unsafe"
)

type StreamHandler struct {
    ch     chan string
    done   chan struct{}
    mu     sync.Mutex
    handle C void
}

var handlers = make(map[*StreamHandler]struct{}{})
var handlersMu sync.RWMutex

//export chunkProxy
func chunkProxy(data *C.char, len C.size_t, user unsafe.Pointer) {
    handlersMu.RLock()
    defer handlersMu.RUnlock()

    handler := (*StreamHandler)(user)
    if handler == nil {
        return
    }

    chunk := C.GoStringN(data, C.int(len))

    select {
    case handler.ch <- chunk:
    default:
    }
}

func StartStream(source string) (chan string, error) {
    ch := make(chan string, 10)
    handler := &StreamHandler{
        ch:   ch,
        done: make(chan struct{}),
    }

    handlersMu.Lock()
    handlers[handler] = struct{}{}
    handlersMu.Unlock()

    cSource := C.CString(source)
    defer C.free(unsafe.Pointer(cSource))

    handle := C.go_start_stream(cSource, unsafe.Pointer(handler))
    handler.handle = handle

    return ch, nil
}

func StopStream(handler *StreamHandler) {
    handler.mu.Lock()
    defer handler.mu.Unlock()

    if handler.handle != nil {
        C.stop_stream(handler.handle)
        handler.handle = nil
    }

    close(handler.ch)

    handlersMu.Lock()
    delete(handlers, handler)
    handlersMu.Unlock()
}

func main() {
    ch, err := StartStream("source-123")
    if err != nil {
        panic(err)
    }

    var wg sync.WaitGroup
    wg.Add(1)

    go func() {
        defer wg.Done()
        dec := json.NewDecoder(ch)

        for {
            select {
            case <-ch:
                var data map[string]interface{}
                if err := dec.Decode(&data); err != nil {
                    fmt.Printf("Parse error: %v\n", err)
                    continue
                }
                fmt.Printf("Received: %v\n", data)
                runtime.Gosched()
            }
        }
    }()

    wg.Wait()
}
```

